}

function mergeHalves(left, right) {
  const merged = [];
  let i = 0;
  let j = 0;
  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) {
      merged.push(left[i]);
      i++;
    } else {
      merged.push(right[j]);
      j++;
    }
  }
  return merged.concat(left.slice(i), right.slice(j)); // one of these two is already empty
}

function mergeSort(nums) {
  if (nums.length <= 1) {
    return nums; // already sorted, nothing to merge or print
  }
  const mid = Math.floor(nums.length / 2);
  const left = mergeSort(nums.slice(0, mid));
  const right = mergeSort(nums.slice(mid));
  const merged = mergeHalves(left, right);
  printRun(merged);
  return merged;
}

const [n, ...nums] = input.trim().split(/\s+/).map(Number);
