#include <iostream>
#include <vector>

void printRun(const std::vector<int>& nums) {
    for (std::size_t i = 0; i < nums.size(); i++) {
        if (i > 0) {
            std::cout << " ";
        }
        std::cout << nums[i];
    }
    std::cout << "\n";
}

std::vector<int> mergeHalves(const std::vector<int>& left, const std::vector<int>& right) {
    std::vector<int> merged;
    std::size_t i = 0;
    std::size_t j = 0;
    while (i < left.size() && j < right.size()) {
        if (left[i] <= right[j]) {
            merged.push_back(left[i]);
            i++;
        } else {
            merged.push_back(right[j]);
            j++;
        }
    }
    // One of these two is already empty.
    merged.insert(merged.end(), left.begin() + i, left.end());
    merged.insert(merged.end(), right.begin() + j, right.end());
    return merged;
}

std::vector<int> mergeSort(const std::vector<int>& nums) {
    if (nums.size() <= 1) {
        return nums;  // already sorted, nothing to merge or print
    }
    std::size_t mid = nums.size() / 2;
    std::vector<int> left = mergeSort(std::vector<int>(nums.begin(), nums.begin() + mid));
    std::vector<int> right = mergeSort(std::vector<int>(nums.begin() + mid, nums.end()));
    std::vector<int> merged = mergeHalves(left, right);
    printRun(merged);
    return merged;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> nums(n);
    for (int i = 0; i < n; i++) {
        std::cin >> nums[i];
    }
    mergeSort(nums);
    return 0;
}

