import java.util.Arrays;
import java.util.Scanner;
import java.util.StringJoiner;

public class Main {
    static void printRun(int[] nums) {
        StringJoiner line = new StringJoiner(" ");
        for (int num : nums) {
            line.add(String.valueOf(num));
        }
        System.out.println(line);
    }

    static int[] mergeHalves(int[] left, int[] right) {
        int[] merged = new int[left.length + right.length];
        int i = 0;
        int j = 0;
        int k = 0;
        while (i < left.length && j < right.length) {
            if (left[i] <= right[j]) {
                merged[k++] = left[i++];
            } else {
                merged[k++] = right[j++];
            }
        }
        // One of these two loops has nothing left to copy.
        while (i < left.length) {
            merged[k++] = left[i++];
        }
        while (j < right.length) {
            merged[k++] = right[j++];
        }
        return merged;
    }

    static int[] mergeSort(int[] nums) {
        if (nums.length <= 1) {
            return nums; // already sorted, nothing to merge or print
        }
        int mid = nums.length / 2;
        int[] left = mergeSort(Arrays.copyOfRange(nums, 0, mid));
        int[] right = mergeSort(Arrays.copyOfRange(nums, mid, nums.length));
        int[] merged = mergeHalves(left, right);
        printRun(merged);
        return merged;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) {
            nums[i] = in.nextInt();
        }
        mergeSort(nums);
    }
}

