package main

import (
	"fmt"
	"strconv"
	"strings"
)

func printRun(nums []int) {
	parts := make([]string, len(nums))
	for i, num := range nums {
		parts[i] = strconv.Itoa(num)
	}
	fmt.Println(strings.Join(parts, " "))
}

func mergeHalves(left, right []int) []int {
	merged := make([]int, 0, len(left)+len(right))
	i, j := 0, 0
	for i < len(left) && j < len(right) {
		if left[i] <= right[j] {
			merged = append(merged, left[i])
			i++
		} else {
			merged = append(merged, right[j])
			j++
		}
	}
	merged = append(merged, left[i:]...) // one of these two is already empty
	return append(merged, right[j:]...)
}

func mergeSort(nums []int) []int {
	if len(nums) <= 1 {
		return nums // already sorted, nothing to merge or print
	}
	mid := len(nums) / 2
	left := mergeSort(nums[:mid])
	right := mergeSort(nums[mid:])
	merged := mergeHalves(left, right)
	printRun(merged)
	return merged
}

func main() {
	var n int
	fmt.Scan(&n)
	nums := make([]int, n)
	for i := range nums {
		fmt.Scan(&nums[i])
	}
	mergeSort(nums)
}

